-- 20261006130000_enforce_mfa.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261006130000') then
    execute $tw_20261006130000$-- MFA is enforced for every API request, not only by the web app (docs/security.md §2).
--
-- Without this, a password alone (an aal1 session) of an account that has a verified second
-- factor could call the Data API directly — skipping the web app's redirect to the verification
-- page — and read or change that account's data. PostgREST runs this function before every
-- request (db-pre-request); the redirect in the web proxy stays as the friendly front door.

create function public.enforce_mfa()
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if (select auth.role()) = 'authenticated'
     and coalesce((select auth.jwt()) ->> 'aal', 'aal1') <> 'aal2'
     and exists (
       select 1 from auth.mfa_factors f
       where f.user_id = (select auth.uid()) and f.status = 'verified'
     ) then
    raise exception 'multi-factor authentication required'
      using errcode = '42501', hint = 'mfa_required';
  end if;
end;
$$;

revoke execute on function public.enforce_mfa() from public;
grant execute on function public.enforce_mfa() to anon, authenticated, service_role;

alter role authenticator set pgrst.db_pre_request to 'public.enforce_mfa';
notify pgrst, 'reload config';
$tw_20261006130000$;
    insert into supabase_migrations.schema_migrations (version, name) values ('20261006130000', 'enforce_mfa');
    raise notice 'applied 20261006130000_enforce_mfa.sql';
  end if;
end $run$;

-- 20261006140000_artist_location.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261006140000') then
    execute $tw_20261006140000$-- Where an artist is from (M6.1, product.md D6: small independent artists from all of Poland).
-- The voivodeship is the reliable filter for discovery; the city is free text until the seeded
-- cities table arrives with events and venues (M8).

create type public.voivodeship as enum (
  'dolnoslaskie', 'kujawsko_pomorskie', 'lubelskie', 'lubuskie', 'lodzkie', 'malopolskie',
  'mazowieckie', 'opolskie', 'podkarpackie', 'podlaskie', 'pomorskie', 'slaskie',
  'swietokrzyskie', 'warminsko_mazurskie', 'wielkopolskie', 'zachodniopomorskie'
);

alter table public.artists
  add column voivodeship public.voivodeship,
  add column city text constraint artists_city_length check (char_length(btrim(city)) between 1 and 80);

create index artists_voivodeship_idx on public.artists (voivodeship) where status = 'active';

-- Owners and managers edit these like the other descriptive columns (RLS policy unchanged).
grant update (voivodeship, city) on public.artists to authenticated;
