-- 20261006150000_search.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261006150000') then
    execute $tw_20261006150000$-- Catalog search (M6.2): artists, releases, tracks — public data only, Polish-aware.
--
-- Matching works on a normalized form (lower case, Polish diacritics removed: "Łódź" → "lodz"),
-- so people can type without Polish characters. Results come from, in order of strength: whole
-- name, name prefix, a word prefix, a substring, then trigram similarity for typos.

create extension if not exists unaccent with schema extensions;
create extension if not exists pg_trgm with schema extensions;

/** lower(unaccent(text)); unaccent itself is only STABLE, the fixed dictionary makes this safe. */
create function public.search_normalize(value text)
returns text
language sql
immutable
parallel safe
set search_path = ''
as $$
  select lower(extensions.unaccent('extensions.unaccent'::regdictionary, coalesce(value, '')));
$$;

create index artists_search_idx on public.artists
  using gin (public.search_normalize(name) extensions.gin_trgm_ops);
create index releases_search_idx on public.releases
  using gin (public.search_normalize(title) extensions.gin_trgm_ops);
create index tracks_search_idx on public.tracks
  using gin (public.search_normalize(title) extensions.gin_trgm_ops);

/**
 * Ranked matches across the public catalog. Security invoker (RLS applies) plus explicit public
 * filters, so even members never see their own drafts in search.
 */
create function public.search_catalog(query text, max_results integer default 8)
returns table (
  kind text,
  id uuid,
  title text,
  artist_name text,
  artist_slug text,
  release_id uuid,
  release_slug text,
  release_title text,
  release_type public.release_type,
  image_id uuid,
  score real
)
language sql
stable
security invoker
set search_path = ''
as $$
  with q as (
    select
      public.search_normalize(btrim(left(query, 80))) as text,
      -- LIKE patterns with the user's %, _ and \ escaped
      replace(replace(replace(public.search_normalize(btrim(left(query, 80))), '\', '\\'), '%', '\%'), '_', '\_') as pattern
  ),
  candidates as (
    select 'artist' as kind, a.id, a.name as title, a.name as artist_name, a.slug::text as artist_slug,
      null::uuid as release_id, null::text as release_slug, null::text as release_title, null::public.release_type as release_type,
      a.image_id, public.search_normalize(a.name) as normalized
    from public.artists a
    where a.status = 'active'
    union all
    select 'release', r.id, r.title, a.name, a.slug::text, r.id, r.slug::text, r.title, r.type,
      r.artwork_image_id, public.search_normalize(r.title)
    from public.releases r
    join public.artists a on a.id = r.artist_id
    where r.status = 'published' and r.publish_at <= now() and a.status = 'active'
    union all
    select 'track', t.id, t.title, a.name, a.slug::text, r.id, r.slug::text, r.title, r.type,
      r.artwork_image_id, public.search_normalize(t.title)
    from public.tracks t
    join public.releases r on r.id = t.release_id
    join public.artists a on a.id = r.artist_id
    where r.status = 'published' and r.publish_at <= now() and a.status = 'active'
  ),
  scored as (
    select c.*,
      case
        when c.normalized = q.text then 1.0
        when c.normalized like q.pattern || '%' then 0.9
        when c.normalized like '% ' || q.pattern || '%' then 0.8
        when c.normalized like '%' || q.pattern || '%' then 0.6
        else extensions.similarity(c.normalized, q.text) * 0.7
      end::real as score
    from candidates c, q
    where char_length(q.text) >= 2
      and (c.normalized like '%' || q.pattern || '%' or extensions.similarity(c.normalized, q.text) > 0.3)
  ),
  ranked as (
    select s.*, row_number() over (partition by s.kind order by s.score desc, s.title) as position
    from scored s
  )
  select r.kind, r.id, r.title, r.artist_name, r.artist_slug, r.release_id, r.release_slug, r.release_title,
    r.release_type, r.image_id, r.score
  from ranked r
  where r.position <= least(greatest(max_results, 1), 20)
  order by case r.kind when 'artist' then 1 when 'release' then 2 else 3 end, r.score desc, r.title;
$$;

grant execute on function public.search_normalize(text) to anon, authenticated;
grant execute on function public.search_catalog(text, integer) to anon, authenticated;
$tw_20261006150000$;
    insert into supabase_migrations.schema_migrations (version, name) values ('20261006150000', 'search');
    raise notice 'applied 20261006150000_search.sql';
  end if;
end $run$;

-- 20261006160000_discover.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261006160000') then
    execute $tw_20261006160000$-- Discover home (M6.3): new music from all of Poland, optionally narrowed to a voivodeship.
-- Public data only (security invoker + explicit public filters). Every row carries the facts the
-- page turns into a true reason ("Debut", "New · 3 days ago", "Suwałki · Podlaskie") —
-- nothing is ranked by engagement yet; there is no listening data to rank by honestly.

/** Newest public releases, at most one per artist (the artist's newest), newest first. */
create function public.discover_releases(region public.voivodeship default null, max_results integer default 12)
returns table (
  release_id uuid,
  release_slug text,
  title text,
  release_type public.release_type,
  publish_at timestamptz,
  artwork_image_id uuid,
  artist_name text,
  artist_slug text,
  city text,
  voivodeship public.voivodeship,
  is_debut boolean
)
language sql
stable
security invoker
set search_path = ''
as $$
  with public_releases as (
    select r.*, a.name as artist_name, a.slug as artist_slug, a.city, a.voivodeship,
      row_number() over (partition by r.artist_id order by r.publish_at desc) as newest,
      count(*) over (partition by r.artist_id) as release_count
    from public.releases r
    join public.artists a on a.id = r.artist_id
    where r.status = 'published' and r.publish_at <= now() and a.status = 'active'
      and (discover_releases.region is null or a.voivodeship = discover_releases.region)
  )
  select p.id, p.slug::text, p.title, p.type, p.publish_at, p.artwork_image_id, p.artist_name,
    p.artist_slug::text, p.city, p.voivodeship, p.release_count = 1
  from public_releases p
  where p.newest = 1
  order by p.publish_at desc
  limit least(greatest(discover_releases.max_results, 1), 48);
$$;

/** Artists by their first public release (newest debuts first). */
create function public.discover_artists(region public.voivodeship default null, max_results integer default 12)
returns table (
  artist_id uuid,
  artist_slug text,
  name text,
  image_id uuid,
  city text,
  voivodeship public.voivodeship,
  verification_status public.artist_verification,
  first_release_at timestamptz,
  release_count integer
)
language sql
stable
security invoker
set search_path = ''
as $$
  select a.id, a.slug::text, a.name, a.image_id, a.city, a.voivodeship, a.verification_status,
    min(r.publish_at), count(r.id)::integer
  from public.artists a
  join public.releases r on r.artist_id = a.id and r.status = 'published' and r.publish_at <= now()
  where a.status = 'active'
    and (discover_artists.region is null or a.voivodeship = discover_artists.region)
  group by a.id
  order by min(r.publish_at) desc
  limit least(greatest(discover_artists.max_results, 1), 48);
$$;

grant execute on function public.discover_releases(public.voivodeship, integer) to anon, authenticated;
grant execute on function public.discover_artists(public.voivodeship, integer) to anon, authenticated;
$tw_20261006160000$;
    insert into supabase_migrations.schema_migrations (version, name) values ('20261006160000', 'discover');
    raise notice 'applied 20261006160000_discover.sql';
  end if;
end $run$;

-- 20261006170000_entitlements.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261006170000') then
    execute $tw_20261006170000$-- Plans and entitlements (M9.1, docs/promotions.md §1–2). The only source of truth for Premium:
-- the web app asks the database which tiers a listener may stream and never infers a plan from the
-- client. Entitlements are never deleted — revocation keeps the row, the reason and who did it.

create type public.entitlement_source as enum ('promo', 'beta', 'admin', 'referral', 'subscription');

/** Data, not code: a new plan is a row. `rank` orders plans when several are active. */
create table public.plans (
  code text primary key constraint plans_code_format check (code ~ '^[a-z][a-z0-9_]{1,31}$'),
  name text not null,
  rank integer not null unique,
  max_quality_tier public.quality_tier not null,
  features jsonb not null default '[]'::jsonb
);

insert into public.plans (code, name, rank, max_quality_tier, features) values
  ('free', 'Free', 0, 'high', '[]'),
  ('premium', 'Premium', 1, 'hires', '["lossless", "hires"]');

create table public.entitlements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  plan_code text not null references public.plans (code),
  source public.entitlement_source not null,
  -- What granted it, for the user and for support: a campaign name, "beta 2026", an admin note.
  source_ref text constraint entitlements_source_ref_length check (char_length(source_ref) <= 120),
  starts_at timestamptz not null default now(),
  ends_at timestamptz,
  granted_by uuid references auth.users (id) on delete set null,
  revoked_at timestamptz,
  revoked_reason text,
  revoked_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  constraint entitlements_period check (ends_at is null or ends_at > starts_at),
  constraint entitlements_revocation check (
    (revoked_at is null and revoked_reason is null)
    or (revoked_at is not null and char_length(revoked_reason) between 5 and 500)
  )
);

create index entitlements_user_idx on public.entitlements (user_id, plan_code, starts_at);

alter table public.plans enable row level security;
alter table public.entitlements enable row level security;

create policy plans_read on public.plans for select to anon, authenticated using (true);
create policy entitlements_read_own on public.entitlements for select to authenticated
  using (user_id = (select auth.uid()));
-- Admins (with MFA) look entitlements up for support and revocation.
create policy entitlements_read_admin on public.entitlements for select to authenticated
  using ((select public.has_app_role('admin')) and coalesce((select auth.jwt()) ->> 'aal', 'aal1') = 'aal2');

revoke all on public.plans, public.entitlements from anon, authenticated;
grant select on public.plans to anon, authenticated;
grant select on public.entitlements to authenticated;

-- ---------------------------------------------------------------------------
-- Effective plan
-- ---------------------------------------------------------------------------

/**
 * The user's effective plan now: the highest-ranked plan with an active entitlement, else free.
 * `ends_at` follows back-to-back entitlements of that plan (stacked codes), null = for life.
 */
create function private.effective_plan(target uuid)
returns table (plan_code text, ends_at timestamptz, source public.entitlement_source, source_ref text)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  current_entitlement public.entitlements;
  horizon timestamptz;
  next_end timestamptz;
  lifetime boolean;
begin
  select e.* into current_entitlement
  from public.entitlements e
  join public.plans p on p.code = e.plan_code
  where e.user_id = target and e.revoked_at is null
    and e.starts_at <= now() and (e.ends_at is null or e.ends_at > now())
  order by p.rank desc, e.ends_at desc nulls first
  limit 1;

  if current_entitlement.id is null then
    return query select 'free'::text, null::timestamptz, null::public.entitlement_source, null::text;
    return;
  end if;

  select exists (
    select 1 from public.entitlements e
    where e.user_id = target and e.plan_code = current_entitlement.plan_code
      and e.revoked_at is null and e.starts_at <= now() and e.ends_at is null
  ) into lifetime;

  if not lifetime then
    horizon := now();
    loop
      select max(e.ends_at) into next_end
      from public.entitlements e
      where e.user_id = target and e.plan_code = current_entitlement.plan_code
        and e.revoked_at is null and e.starts_at <= horizon and e.ends_at > horizon;
      exit when next_end is null;
      horizon := next_end;
    end loop;
  end if;

  return query select current_entitlement.plan_code,
    case when lifetime then null else horizon end,
    current_entitlement.source, current_entitlement.source_ref;
end;
$$;

revoke execute on function private.effective_plan(uuid) from public, anon, authenticated;

/** The caller's plan (anonymous listeners are on free) with what it unlocks. */
create function public.my_plan()
returns table (
  plan_code text,
  plan_name text,
  max_quality_tier public.quality_tier,
  ends_at timestamptz,
  source public.entitlement_source,
  source_ref text
)
language sql
stable
security definer
set search_path = ''
as $$
  select p.code, p.name, p.max_quality_tier, e.ends_at, e.source, e.source_ref
  from private.effective_plan((select auth.uid())) e
  join public.plans p on p.code = e.plan_code;
$$;

revoke execute on function public.my_plan() from public;
grant execute on function public.my_plan() to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Granting (shared by admin grants, beta and — in M9.2 — promo codes)
-- ---------------------------------------------------------------------------

/**
 * Grants `plan` for `duration` (null = for life). A time-limited grant starts when the user's
 * current run of that plan ends, so stacked grants add time instead of overlapping.
 * Raises `already_lifetime` (P0001, hint) when the user already has that plan for life.
 */
create function private.grant_entitlement(
  target uuid,
  plan text,
  duration interval,
  source public.entitlement_source,
  source_ref text,
  granted_by uuid
)
returns public.entitlements
language plpgsql
security definer
set search_path = ''
as $$
declare
  start_at timestamptz := now();
  horizon timestamptz;
  granted public.entitlements;
begin
  if not exists (select 1 from public.plans p where p.code = plan and p.code <> 'free') then
    raise exception 'unknown plan %', plan using errcode = 'P0002';
  end if;
  -- Serialize grants per user so two concurrent grants cannot both start "now".
  perform pg_advisory_xact_lock(hashtextextended('entitlements:' || target::text, 0));

  if exists (
    select 1 from public.entitlements e
    where e.user_id = target and e.plan_code = plan and e.revoked_at is null
      and e.starts_at <= now() and e.ends_at is null
  ) then
    raise exception 'already has % for life', plan using errcode = 'P0001', hint = 'already_lifetime';
  end if;

  if duration is not null then
    horizon := now();
    loop
      select max(e.ends_at) into start_at
      from public.entitlements e
      where e.user_id = target and e.plan_code = plan and e.revoked_at is null
        and e.starts_at <= horizon and e.ends_at > horizon;
      exit when start_at is null;
      horizon := start_at;
    end loop;
    start_at := horizon;
  end if;

  insert into public.entitlements (user_id, plan_code, source, source_ref, starts_at, ends_at, granted_by)
  values (target, plan, grant_entitlement.source, grant_entitlement.source_ref, start_at,
    case when duration is null then null else start_at + duration end, grant_entitlement.granted_by)
  returning * into granted;

  perform private.write_audit('entitlement.grant', 'user', target::text, null,
    jsonb_build_object('entitlement', granted.id, 'plan', plan, 'source', grant_entitlement.source,
      'source_ref', grant_entitlement.source_ref, 'starts_at', granted.starts_at, 'ends_at', granted.ends_at));
  return granted;
end;
$$;

revoke execute on function private.grant_entitlement(uuid, text, interval, public.entitlement_source, text, uuid)
  from public, anon, authenticated;

/** Admin (with MFA) grants a plan for `days` days, or for life when `days` is null. */
create function public.admin_grant_entitlement(target_user uuid, plan text, days integer, note text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_staff('admin');
  if days is not null and days not between 1 and 3660 then
    raise exception 'days must be between 1 and 3660' using errcode = '22023';
  end if;
  if char_length(coalesce(trim(note), '')) not between 3 and 120 then
    raise exception 'a note (3–120 characters) is required' using errcode = '22023';
  end if;
  return (private.grant_entitlement(target_user, plan,
    case when days is null then null else make_interval(days => days) end,
    'admin', trim(note), (select auth.uid()))).id;
end;
$$;

/** Admin (with MFA) revokes an entitlement with a reason; the row stays. */
create function public.admin_revoke_entitlement(entitlement uuid, reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  previous public.entitlements;
begin
  perform public.require_staff('admin');
  if char_length(coalesce(trim(reason), '')) not between 5 and 500 then
    raise exception 'a reason (5–500 characters) is required' using errcode = '22023';
  end if;
  select * into previous from public.entitlements e where e.id = entitlement for update;
  if previous.id is null then
    raise exception 'entitlement not found' using errcode = 'P0002';
  end if;
  if previous.revoked_at is not null then
    return;
  end if;
  update public.entitlements e
  set revoked_at = now(), revoked_reason = trim(reason), revoked_by = (select auth.uid())
  where e.id = entitlement;
  perform private.write_audit('entitlement.revoke', 'user', previous.user_id::text,
    jsonb_build_object('entitlement', entitlement, 'plan', previous.plan_code, 'ends_at', previous.ends_at),
    jsonb_build_object('reason', trim(reason)));
end;
$$;

/** Server-side bootstrap (secret key only): `scripts/grant-plan.mjs`, beta testers, E2E. */
create function public.system_grant_entitlement(
  target_email text,
  plan text,
  days integer,
  source public.entitlement_source,
  note text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  target uuid;
begin
  select u.id into target from auth.users u where lower(u.email) = lower(target_email);
  if target is null then
    raise exception 'no user with this email' using errcode = 'P0002';
  end if;
  return (private.grant_entitlement(target, plan,
    case when days is null then null else make_interval(days => days) end,
    system_grant_entitlement.source, note, null)).id;
end;
$$;

revoke execute on function public.admin_grant_entitlement(uuid, text, integer, text) from public, anon;
revoke execute on function public.admin_revoke_entitlement(uuid, text) from public, anon;
grant execute on function public.admin_grant_entitlement(uuid, text, integer, text) to authenticated;
grant execute on function public.admin_revoke_entitlement(uuid, text) to authenticated;
revoke execute on function public.system_grant_entitlement(text, text, integer, public.entitlement_source, text)
  from public, anon, authenticated;
grant execute on function public.system_grant_entitlement(text, text, integer, public.entitlement_source, text)
  to service_role;
