    raise notice 'applied 20261007130000_query_review.sql';
  end if;
end $run$;

-- 20261007140000_listening_partitions_job.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261007140000') then
    execute $tw_20261007140000$-- Listening history partitions are kept ahead automatically (M11.7). A monthly pg_cron job makes
-- sure the next months exist. If a month was missed and its rows already landed in the default
-- partition, they are moved into the new partition in the same transaction (attaching a partition
-- over rows the default partition holds would otherwise fail).

/** Ensures partitions for this month and `months_ahead` more; returns how many it created. */
create function private.ensure_listening_partitions(months_ahead integer default 3)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  first date;
  name text;
  created integer := 0;
  rows_to_move public.listening_events[];
begin
  for m in 0..greatest(months_ahead, 0) loop
    first := (date_trunc('month', now()) + make_interval(months => m))::date;
    name := format('listening_events_%s', to_char(first, 'YYYY_MM'));
    continue when to_regclass(format('private.%I', name)) is not null;

    -- Rows already in the default partition for this month (a missed run) move with it.
    with moved as (
      delete from private.listening_events_default d
      where d.started_at >= first and d.started_at < (first + interval '1 month')
      returning d.*
    )
    select array_agg(row(moved.*)::public.listening_events) into rows_to_move from moved;

    execute format(
      'create table private.%I partition of public.listening_events for values from (%L) to (%L)',
      name, first, (first + interval '1 month')::date);
    if rows_to_move is not null then
      insert into public.listening_events select * from unnest(rows_to_move);
    end if;
    created := created + 1;
  end loop;
  return created;
end;
$$;

revoke execute on function private.ensure_listening_partitions(integer) from public, anon, authenticated;

create extension if not exists pg_cron with schema pg_catalog;

-- 03:15 on the first day of every month; keeps three months ahead.
select cron.schedule('listening-partitions', '15 3 1 * *',
  $$select private.ensure_listening_partitions(3)$$);
$tw_20261007140000$;
    insert into supabase_migrations.schema_migrations (version, name) values ('20261007140000', 'listening_partitions_job');
    raise notice 'applied 20261007140000_listening_partitions_job.sql';
  end if;
end $run$;

-- 20261007150000_listening_shares.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261007150000') then
    execute $tw_20261007150000$-- Monthly user-centric listening shares (D2, database.md §3.6, promotions.md). The base for future
-- payouts: how one listener's month splits across artists. Nothing is paid from it yet — Tunewick
-- has no paid plans — but the data model records attribution from day one.
-- A play qualifies at >= 30 s and never as a soundcheck. Months are closed by a monthly job and can
-- be recomputed (idempotent) while raw events exist. On account deletion the shares are detached
-- (user_id null) so accounting totals survive without the person (legal L4 to confirm).

create table public.listening_monthly_artist_shares (
  id bigint generated always as identity primary key,
  user_id uuid references auth.users (id) on delete set null,
  month date not null constraint listening_shares_month check (month = date_trunc('month', month)::date),
  artist_id uuid not null references public.artists (id) on delete cascade,
  qualified_plays integer not null constraint listening_shares_plays check (qualified_plays > 0),
  ms_played bigint not null,
  computed_at timestamptz not null default now(),
  constraint listening_shares_unique unique (user_id, month, artist_id)
);

create index listening_shares_month_artist_idx on public.listening_monthly_artist_shares (month, artist_id);

alter table public.listening_monthly_artist_shares enable row level security;
-- A listener sees their own months (transparency, export); nobody writes through the API.
create policy listening_shares_own_read on public.listening_monthly_artist_shares for select to authenticated
  using (user_id = (select auth.uid()));
revoke all on public.listening_monthly_artist_shares from anon, authenticated;
grant select on public.listening_monthly_artist_shares to authenticated;

/** Recomputes one month from raw listens; returns the number of share rows written. */
create function private.aggregate_listening_month(month date)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  first date := date_trunc('month', month)::date;
  written integer;
begin
  delete from public.listening_monthly_artist_shares s where s.month = first and s.user_id is not null;
  insert into public.listening_monthly_artist_shares (user_id, month, artist_id, qualified_plays, ms_played)
  select e.user_id, first, e.artist_id, count(*), sum(e.ms_played)
  from public.listening_events e
  where e.started_at >= first and e.started_at < first + interval '1 month'
    and e.ms_played >= 30000 and not e.soundcheck
  group by e.user_id, e.artist_id;
  get diagnostics written = row_count;
  return written;
end;
$$;

revoke execute on function private.aggregate_listening_month(date) from public, anon, authenticated;

/** Real listener numbers for an artist's team: last six closed months. */
create function public.artist_monthly_listening(artist uuid)
returns table (month date, listeners integer, qualified_plays integer)
language sql
stable
security definer
set search_path = ''
as $$
  select s.month, count(distinct s.user_id)::integer, sum(s.qualified_plays)::integer
  from public.listening_monthly_artist_shares s
  where s.artist_id = artist and public.is_artist_member(artist)
    and s.month >= (date_trunc('month', now()) - interval '6 months')::date
  group by s.month
  order by s.month desc;
$$;

/** Admin: one month's totals per artist (base for the payout statement). */
create function public.admin_listening_shares(month date)
returns table (artist_id uuid, artist_name text, artist_slug text, listeners integer, qualified_plays integer, hours numeric)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_staff('admin');
  return query
  select a.id, a.name, a.slug::text, count(distinct s.user_id)::integer, sum(s.qualified_plays)::integer,
    round(sum(s.ms_played) / 3600000.0, 1)
  from public.listening_monthly_artist_shares s
  join public.artists a on a.id = s.artist_id
  where s.month = date_trunc('month', admin_listening_shares.month)::date
  group by a.id
  order by sum(s.qualified_plays) desc
  limit 200;
end;
$$;

revoke execute on function public.artist_monthly_listening(uuid) from public, anon;
revoke execute on function public.admin_listening_shares(date) from public, anon;
grant execute on function public.artist_monthly_listening(uuid) to authenticated;
grant execute on function public.admin_listening_shares(date) to authenticated;

-- 04:00 on the 2nd: close the previous month (late listens of the month's last night included).
select cron.schedule('listening-shares', '0 4 2 * *',
  $$select private.aggregate_listening_month((date_trunc('month', now()) - interval '1 month')::date)$$);
$tw_20261007150000$;
    insert into supabase_migrations.schema_migrations (version, name) values ('20261007150000', 'listening_shares');
    raise notice 'applied 20261007150000_listening_shares.sql';
  end if;
end $run$;

-- 20261007160000_retention.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261007160000') then
    execute $tw_20261007160000$-- Data retention made real (privacy policy §6, database.md §6). A daily pg_cron job removes what
-- the privacy policy says is not kept:
--   raw listening events  older than 25 months (whole monthly partitions are dropped);
--   promo code attempts   older than 90 days;
--   playback telemetry    older than 13 months; hourly rate counters older than 2 days;
--   staff audit log       older than 2 years.
-- Monthly listening shares (D2) are kept: they are the accounting base for payouts.

-- The audit log stays tamper-resistant: no updates ever, and deletes only of entries past the
-- two-year retention (which is what the daily job removes).
create or replace function private.audit_log_is_append_only()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' and old.created_at < now() - interval '2 years' then
    return old;
  end if;
  raise exception 'audit_log is append-only' using errcode = '42501';
end;
$$;

/** Applies the retention rules; returns what was removed, for the job log. */
create function private.apply_retention()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cutoff date := (date_trunc('month', now()) - interval '25 months')::date;
  part record;
  dropped integer := 0;
  default_rows integer;
  attempts integer;
  metrics integer;
  counters integer;
  audit integer;
begin
  -- Monthly partitions whose whole month ended before the cutoff.
  for part in
    select c.relname, to_date(right(c.relname, 7), 'YYYY_MM') as month
    from pg_inherits i
    join pg_class c on c.oid = i.inhrelid
    join pg_namespace n on n.oid = c.relnamespace
    where i.inhparent = 'public.listening_events'::regclass and n.nspname = 'private'
      and c.relname ~ '^listening_events_[0-9]{4}_[0-9]{2}$'
  loop
    if part.month < cutoff then
      execute format('drop table private.%I', part.relname);
      dropped := dropped + 1;
    end if;
  end loop;
  delete from private.listening_events_default d where d.started_at < cutoff;
  get diagnostics default_rows = row_count;

  delete from private.promo_attempts a where a.attempted_at < now() - interval '90 days';
  get diagnostics attempts = row_count;
  delete from private.playback_metrics m where m.day < (now() - interval '13 months')::date;
  get diagnostics metrics = row_count;
  delete from private.playback_report_counts c where c.hour < now() - interval '2 days';
  get diagnostics counters = row_count;
  delete from private.audit_log l where l.created_at < now() - interval '2 years';
  get diagnostics audit = row_count;

  return jsonb_build_object('listening_partitions', dropped, 'listening_default_rows', default_rows,
    'promo_attempts', attempts, 'playback_metrics', metrics, 'rate_counters', counters, 'audit_log', audit);
end;
$$;

revoke execute on function private.apply_retention() from public, anon, authenticated;

-- 03:45 every day.
select cron.schedule('retention', '45 3 * * *', $$select private.apply_retention()$$);
$tw_20261007160000$;
    insert into supabase_migrations.schema_migrations (version, name) values ('20261007160000', 'retention');
    raise notice 'applied 20261007160000_retention.sql';
  end if;
end $run$;

