do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261008110000') then
    execute $tw_20261008110000$-- Discovery ledger (X-DB2, docs/discovery-expansion.md §5). Every point a listener earns is a row
-- in discovery_points with an idempotency key, written only by the database after its own checks.
-- Score, streaks, goals, records and rankings are all derived from it — never from listening time
-- alone. Previews from the Discover feed are soundcheck listens (listening_events.soundcheck, M7.4):
-- recorded, never counted towards payouts (D2).

-- ---------------------------------------------------------------------------
-- Saves: the listener's "saved from Discover" crate (Like stays the existing track_likes).
-- ---------------------------------------------------------------------------
create table public.track_saves (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  track_id uuid not null references public.tracks (id) on delete cascade,
