-- 20261012100000_worker_wake.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261012100000') then
    execute $tw_20261012100000$-- Wakes the audio worker when there is work (docs/deployment.md §3b).
--
-- On Fly.io the worker stops itself after a few idle minutes (it pays only while it runs); any HTTP
-- request to the app starts it again. New uploads, images, share clips and storage deletions send
-- one such request (at most every 20 seconds); an hourly wake covers retries of crashed jobs and the
-- reanalysis backfill. With no URL configured (local, CI, an always-on worker) nothing is sent.
--
--   update private.worker_wake set url = 'https://<fly-app>.fly.dev/wake';

create extension if not exists pg_net;

create table private.worker_wake (
  id boolean primary key default true check (id),
  url text check (url is null or url ~ '^https://'),
  last_sent_at timestamptz
);
insert into private.worker_wake default values;
revoke all on private.worker_wake from public, anon, authenticated;

/** Sends one wake request unless one went out in the last 20 seconds (or `always`). */
create function private.wake_worker(always boolean default false)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  target text;
begin
  update private.worker_wake w
  set last_sent_at = now()
  where w.url is not null
    and (always or w.last_sent_at is null or w.last_sent_at < now() - interval '20 seconds')
  returning w.url into target;
  if target is null then
    return false;
  end if;
  perform net.http_get(url := target, timeout_milliseconds := 10000);
  return true;
end;
$$;

revoke execute on function private.wake_worker(boolean) from public, anon, authenticated;

create function private.wake_worker_on_job()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.wake_worker();
  return null;
end;
$$;

create trigger track_audio_uploads_wake_worker
  after insert or update of status on public.track_audio_uploads
  for each row when (new.status = 'uploaded')
  execute function private.wake_worker_on_job();

create trigger images_wake_worker
  after insert or update of status on public.images
  for each row when (new.status = 'uploaded')
  execute function private.wake_worker_on_job();

create trigger share_clips_wake_worker
  after insert or update of status on public.share_clips
  for each row when (new.status = 'queued')
  execute function private.wake_worker_on_job();

create trigger storage_deletions_wake_worker
  after insert on private.storage_deletions
  for each statement
  execute function private.wake_worker_on_job();

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('worker-wake', '7 * * * *', $cron$select private.wake_worker(true)$cron$);
  end if;
end;
$$;
$tw_20261012100000$;
    insert into supabase_migrations.schema_migrations (version, name) values ('20261012100000', 'worker_wake');
    raise notice 'applied 20261012100000_worker_wake.sql';
  end if;
end $run$;

-- 20261012110000_monthly_recaps.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261012110000') then
    execute $tw_20261012110000$-- M14.6 Monthly recap (docs/discovery-v2.md M14.6).
--
-- A month's recap is the listener's statistics for that local month (private.listening_stats).
-- Once the month is over it never changes, so the first read stores it and later reads (the page,
-- every share card) are one indexed row. The running month is computed live and never stored.

create table public.listening_recaps (
  user_id uuid not null references auth.users (id) on delete cascade,
  month date not null check (extract(day from month) = 1),
  stats jsonb not null,
  created_at timestamptz not null default now(),
  primary key (user_id, month)
);

alter table public.listening_recaps enable row level security;
create policy "listening recaps own" on public.listening_recaps
  for select to authenticated using (user_id = (select auth.uid()));
revoke all on public.listening_recaps from anon, authenticated;
grant select on public.listening_recaps to authenticated;

/**
 * The caller's recap for the local month containing `month_start` (any day of it). Not before the
 * listener joined and not in the future; null then.
 */
create function public.my_month_recap(month_start date)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  listener uuid := (select auth.uid());
  first_day date := date_trunc('month', month_start)::date;
  next_month date := (date_trunc('month', month_start) + interval '1 month')::date;
  today date;
  joined date;
  result jsonb;
begin
  if listener is null then
    raise exception 'sign in required' using errcode = '42501';
  end if;
  today := (now() at time zone private.listener_tz(listener))::date;
  select (u.created_at at time zone private.listener_tz(listener))::date into joined
  from auth.users u where u.id = listener;
  if first_day > today or next_month <= date_trunc('month', joined)::date then
    return null;
  end if;

  select r.stats into result from public.listening_recaps r
  where r.user_id = listener and r.month = first_day;
  if result is not null then
    return result;
  end if;

  result := private.listening_stats(listener, first_day, next_month);
  -- Stored from the second day after the month: late listens (the daily aggregates refresh every
  -- few minutes) are in by then.
  if next_month < today then
    insert into public.listening_recaps (user_id, month, stats)
    values (listener, first_day, result)
    on conflict (user_id, month) do nothing;
  end if;
  return result;
end;
$$;

revoke execute on function public.my_month_recap(date) from public, anon;
grant execute on function public.my_month_recap(date) to authenticated;
