    raise notice 'applied 20261013130000_profile_images.sql';
  end if;
end $run$;

-- 20261014090000_playlist_covers.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261014090000') then
    execute $tw_20261014090000$-- Playlist covers: the artwork of the first (up to) four different releases in a playlist, in
-- playlist order, for a 2x2 mosaic. One call for a whole list of playlists. Runs as the caller
-- (security invoker): RLS decides which playlists, tracks and releases they may see.

create function public.playlist_covers(ids uuid[])
returns table (playlist_id uuid, artwork_ids uuid[])
language sql
stable
security invoker
set search_path = ''
as $$
  select l.id, coalesce(c.artwork_ids, '{}')
  from unnest(ids[1:200]) as l (id)
  left join lateral (
    select array_agg(x.artwork_image_id order by x.first_position) as artwork_ids
    from (
      select r.artwork_image_id, min(pt.position) as first_position
      from public.playlist_tracks pt
      join public.tracks t on t.id = pt.track_id
      join public.releases r on r.id = t.release_id
      where pt.playlist_id = l.id
        and r.artwork_image_id is not null
        and public.release_is_public(r.id)
      group by r.artwork_image_id
      order by first_position
      limit 4
    ) x
  ) c on true;
$$;

revoke execute on function public.playlist_covers(uuid[]) from public;
grant execute on function public.playlist_covers(uuid[]) to anon, authenticated;
$tw_20261014090000$;
    insert into supabase_migrations.schema_migrations (version, name) values ('20261014090000', 'playlist_covers');
    raise notice 'applied 20261014090000_playlist_covers.sql';
  end if;
end $run$;

-- 20261015090000_artist_track_stats.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261015090000') then
    execute $tw_20261015090000$-- Per-song numbers for an artist's team (Artist → Manage): the last 28 days of listening (a play
-- counts at 30 s, soundchecks never) and what listeners kept doing with each song - saves, likes,
-- playlist adds. Counts only, never who. Team members only; anyone else gets no rows.
create function public.artist_track_stats(artist uuid)
returns table (
  track_id uuid,
  title text,
  release_title text,
  listeners_28d integer,
  plays_28d integer,
  completion_rate numeric,
  saves integer,
  likes integer,
  playlist_adds integer
)
language sql
stable
security definer
set search_path = ''
as $$
  with songs as (
    select t.id, t.title, r.title as release_title, r.publish_at, t.disc_number, t.track_number
    from public.tracks t
    join public.releases r on r.id = t.release_id
    where r.artist_id = artist and r.status = 'published' and public.is_artist_member(artist)
  ),
  plays as (
    select e.track_id, count(distinct e.user_id) as listeners, count(*) as plays,
      avg(case when e.completed then 1.0 else 0.0 end) as completion
    from public.listening_events e
    where e.artist_id = artist and e.started_at >= now() - interval '28 days'
      and e.ms_played >= 30000 and not e.soundcheck
    group by e.track_id
  )
  select s.id, s.title, s.release_title,
    coalesce(p.listeners, 0)::integer,
    coalesce(p.plays, 0)::integer,
    round(p.completion, 2),
    (select count(*) from public.track_saves x where x.track_id = s.id)::integer,
    (select count(*) from public.track_likes x where x.track_id = s.id)::integer,
    (select count(distinct x.playlist_id) from public.playlist_tracks x where x.track_id = s.id)::integer
  from songs s
  left join plays p on p.track_id = s.id
  order by coalesce(p.plays, 0) desc, s.publish_at desc nulls last, s.disc_number, s.track_number
  limit 200;
$$;

revoke execute on function public.artist_track_stats(uuid) from public, anon;
grant execute on function public.artist_track_stats(uuid) to authenticated;
$tw_20261015090000$;
    insert into supabase_migrations.schema_migrations (version, name) values ('20261015090000', 'artist_track_stats');
    raise notice 'applied 20261015090000_artist_track_stats.sql';
  end if;
end $run$;

-- 20261016090000_releases_playback.sql
do $run$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261016090000') then
    execute $tw_20261016090000$-- Playback for many releases in one call: what release_playback returns per release, plus the
-- release's accepted cover variants. Pages that list music (browse, search, playlists, library,
-- charts) made three requests per release before (playback, cover id, cover variants); across
-- regions every request costs a round trip. Same visibility rule: release_playback checks
-- can_view_release, and a cover is only returned with rows the caller may see.
create function public.releases_playback(releases uuid[])
returns table (
  release_id uuid,
  track_id uuid,
  upload_id uuid,
  source jsonb,
  variants jsonb,
  artwork jsonb
)
language sql
stable
security definer
set search_path = ''
as $$
  select r.id, p.track_id, p.upload_id, p.source, p.variants,
    case when i.status = 'accepted' then i.variants end
  from unnest(releases[1:100]) with ordinality as x(id, ord)
  join public.releases r on r.id = x.id
  left join public.images i on i.id = r.artwork_image_id
  cross join lateral public.release_playback(r.id) with ordinality as p(track_id, upload_id, source, variants, n)
  order by x.ord, p.n;
$$;

revoke execute on function public.releases_playback(uuid[]) from public;
grant execute on function public.releases_playback(uuid[]) to anon, authenticated;
$tw_20261016090000$;
    insert into supabase_migrations.schema_migrations (version, name) values ('20261016090000', 'releases_playback');
    raise notice 'applied 20261016090000_releases_playback.sql';
  end if;
end $run$;

